PRODUCER_GAIN = 2
CLICK_GAIN = 2
BOOST_GAIN = 10
MAX_BOOST = 30
PRICE_INCREASE = 15
DEFAULT_PROFILE_BY_LEAGUE = {
    1: "rookie",
    2: "manager",
    3: "magnate",
}
PROFILE_ALIASES = {
    "auto": None,
    "default": None,
    "balanced": "manager",
    "builder": "manager",
    "innovator": "magnate",
}
PROFILE_SETTINGS = {
    "rookie": {
        "collect_rate": 0.82,
        "capital_weight": 1.00,
        "quantities": (1,),
    },
    "manager": {
        "collect_rate": 0.58,
        "capital_weight": 0.55,
        "quantities": (1, 10),
    },
    "magnate": {
        "collect_rate": 0.45,
        "capital_weight": 0.24,
        "quantities": (1, 10, 100),
    },
}


def batch_cost(unit_price, quantity):
    progressive = unit_price * PRICE_INCREASE * quantity * (quantity - 1)
    return unit_price * quantity + (progressive + 199) // 200


def fixed_offer(zone, name, unit_price, coupon_count, supports_hundreds):
    cost10 = batch_cost(unit_price, 10)
    if coupon_count > 0:
        cost10 -= cost10 * 20 // 100
    return {
        "zone": zone,
        "name": name,
        "cost1": unit_price,
        "cost10": cost10,
        "cost100": batch_cost(unit_price, 100) if supports_hundreds else -1,
        "max_buyable": 0,
        "cost_max": 0,
    }


def boost_offer(zone, unit_price, boost_turns, cash):
    capacity = (MAX_BOOST - boost_turns) // BOOST_GAIN
    max_buyable = 0
    for quantity in range(1, capacity + 1):
        if batch_cost(unit_price, quantity) <= cash:
            max_buyable = quantity
    return {
        "zone": zone,
        "name": "BOOST",
        "cost1": unit_price,
        "cost10": -1,
        "cost100": -1,
        "max_buyable": max_buyable,
        "cost_max": batch_cost(unit_price, max_buyable) if max_buyable else 0,
    }


def build_actions(zones, global_boost, global_boost_price, cash, coupon_count):
    actions = []
    supports_hundreds = global_boost_price >= 0
    for name in ZONE_ORDER:
        zone = zones[name]
        if zone["producer_price"] < 0:
            continue
        actions.append({
            "zone": name,
            "name": "COLLECT",
            "cost1": 0,
            "cost10": -1,
            "cost100": -1,
            "max_buyable": 1,
            "cost_max": 0,
        })
        actions.append(fixed_offer(
            name,
            "PRODUCER",
            zone["producer_price"],
            coupon_count,
            supports_hundreds,
        ))
        if zone["click_upgrade_price"] >= 0:
            actions.append(fixed_offer(
                name,
                "CLICK_UPGRADE",
                zone["click_upgrade_price"],
                coupon_count,
                supports_hundreds,
            ))
        if zone["boost_price"] >= 0:
            actions.append(boost_offer(
                name,
                zone["boost_price"],
                zone["boost"],
                cash,
            ))
    if global_boost_price >= 0:
        actions.append(boost_offer("GLOBAL", global_boost_price, global_boost, cash))
    return actions


def read_turn():
    line = sys.stdin.readline()
    if not line:
        return None
    values = line.split()
    if len(values) != 8:
        raise ValueError("Expected eight values on the global line")
    turn = int(values[0])
    cash = int(values[1])
    total_earned = int(values[2])
    opponent_total = int(values[3])
    last_result = values[4]
    global_boost = int(values[5])
    global_boost_price = int(values[6])
    coupon_count = int(values[7])

    zones = {}
    for _ in range(3):
        (
            name,
            click_value,
            income,
            purchased_click,
            purchased_producer,
            boost,
            producer_price,
            click_upgrade_price,
            boost_price,
        ) = sys.stdin.readline().split()
        zones[name] = {
            "name": name,
            "active": int(producer_price) >= 0,
            "click": int(click_value),
            "income": int(income),
            "boost": int(boost),
            "purchased_click": int(purchased_click),
            "purchased_producer": int(purchased_producer),
            "producer_price": int(producer_price),
            "click_upgrade_price": int(click_upgrade_price),
            "boost_price": int(boost_price),
        }

    return {
        "turn": turn,
        "cash": cash,
        "total_earned": total_earned,
        "opponent_total": opponent_total,
        "global_boost": global_boost,
        "global_boost_price": global_boost_price,
        "last_result": last_result,
        "coupon_count": coupon_count,
        "zones": zones,
        "actions": build_actions(
            zones,
            global_boost,
            global_boost_price,
            cash,
            coupon_count,
        ),
    }


def configuration_for(state):
    if state["global_boost_price"] >= 0:
        league = 3
    elif any(zone["click_upgrade_price"] >= 0 for zone in state["zones"].values()):
        league = 2
    else:
        league = 1
    return {
        "league": league,
        "max_turns": {1: 80, 2: 120, 3: 150}[league],
        "producer_gain": PRODUCER_GAIN,
        "click_gain": CLICK_GAIN,
        "boost_gain": BOOST_GAIN,
        "max_boost": MAX_BOOST,
        "price_increase": PRICE_INCREASE,
    }


def resolve_profile(configuration):
    requested = sys.argv[1].lower() if len(sys.argv) > 1 else "auto"
    requested = PROFILE_ALIASES.get(requested, requested)
    if requested is None:
        return DEFAULT_PROFILE_BY_LEAGUE[configuration["league"]]
    if requested not in PROFILE_SETTINGS:
        return DEFAULT_PROFILE_BY_LEAGUE[configuration["league"]]
    return requested


def new_memory():
    return {
        "unlocked": set(),
        "successful_batch_ten": False,
    }


def update_memory(memory, state):
    if state["coupon_count"] > 0:
        memory["successful_batch_ten"] = True


def remaining_turns(state, configuration):
    return max(0, configuration["max_turns"] - state["turn"])


def active_zones(state):
    return [name for name in ZONE_ORDER if state["zones"][name]["active"]]


def action_order(action):
    names = {"PRODUCER": 3, "CLICK_UPGRADE": 2, "BOOST": 1, "COLLECT": 0}
    return names.get(action["name"], -1)


def zone_order(zone):
    return len(ZONE_ORDER) - ZONE_ORDER.index(zone) if zone in ZONE_ORDER else 0


def best_collect(state):
    best = None
    for action in state["actions"]:
        if action["name"] != "COLLECT":
            continue
        value = state["zones"][action["zone"]]["click"]
        candidate = (value, zone_order(action["zone"]), action["zone"])
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return "WAIT", 0
    return "CLICK {} COLLECT 1".format(best[2]), best[0]


def quantity_costs(action, profile_name, affordable_only, cash):
    allowed = PROFILE_SETTINGS[profile_name]["quantities"]
    result = []
    for quantity, key in ((1, "cost1"), (10, "cost10"), (100, "cost100")):
        cost = action[key]
        if quantity not in allowed or cost < 0:
            continue
        if affordable_only and cost > cash:
            continue
        result.append((quantity, cost, str(quantity)))
    return result


def current_market_factor(state, zone_name):
    zone = state["zones"][zone_name]
    return (2 if zone["boost"] > 0 else 1) * (2 if state["global_boost"] > 0 else 1)


def market_factor_at(state, zone_name, offset, local_duration=None, global_duration=None):
    zone = state["zones"][zone_name]
    local = zone["boost"] if local_duration is None else local_duration
    global_boost = state["global_boost"] if global_duration is None else global_duration
    return (2 if local > offset else 1) * (2 if global_boost > offset else 1)


def base_auto_multiplier(state, zone_name):
    zone = state["zones"][zone_name]
    purchased_income = PRODUCER_GAIN * zone["purchased_producer"]
    if purchased_income == 0:
        return 1000
    effective_without_market = zone["income"] / float(current_market_factor(state, zone_name))
    return min(3000, max(1000, int(effective_without_market * 1000 / purchased_income)))


def base_manual_multiplier(state, zone_name):
    zone = state["zones"][zone_name]
    purchased_click = 5 + CLICK_GAIN * zone["purchased_click"]
    effective_without_market = zone["click"] / float(current_market_factor(state, zone_name))
    return min(3000, max(1000, int(effective_without_market * 1000 / purchased_click)))


def producer_future_gain(state, configuration, zone_name, quantity):
    turns = remaining_turns(state, configuration)
    if turns == 0:
        return 0.0
    base_bp = base_auto_multiplier(state, zone_name)
    total = 0.0
    for offset in range(1, turns + 1):
        total += (
            configuration["producer_gain"]
            * quantity
            * base_bp
            * market_factor_at(state, zone_name, offset)
            / 1000.0
        )
    return total


def click_zone_share(state, configuration, zone_name, quantity, profile_name):
    projected = state["zones"][zone_name]["click"] + configuration["click_gain"] * quantity
    best_other = max(
        state["zones"][name]["click"]
        for name in active_zones(state)
        if name != zone_name
    ) if len(active_zones(state)) > 1 else 0
    if projected >= best_other:
        return 0.90 if profile_name == "magnate" else 0.78
    return 0.18


def click_future_gain(state, configuration, zone_name, quantity, profile_name):
    turns = remaining_turns(state, configuration)
    if turns == 0:
        return 0.0
    collect_rate = PROFILE_SETTINGS[profile_name]["collect_rate"]
    share = click_zone_share(state, configuration, zone_name, quantity, profile_name)
    expected_clicks = turns * collect_rate * share
    base_bp = base_manual_multiplier(state, zone_name)
    average_market_factor = sum(
        market_factor_at(state, zone_name, offset)
        for offset in range(1, turns + 1)
    ) / float(turns)
    gain = (
        configuration["click_gain"]
        * quantity
        * expected_clicks
        * base_bp
        * average_market_factor
        / 1000.0
    )
    return gain


def projected_levels(state, action, quantity):
    click_levels = {}
    producer_levels = {}
    for name in active_zones(state):
        zone = state["zones"][name]
        click_levels[name] = zone["purchased_click"]
        producer_levels[name] = zone["purchased_producer"]
    if action["zone"] in click_levels:
        if action["name"] == "CLICK_UPGRADE":
            click_levels[action["zone"]] += quantity
        elif action["name"] == "PRODUCER":
            producer_levels[action["zone"]] += quantity
    return click_levels, producer_levels


def visible_trophy_bonus(state, configuration, memory, action, quantity, profile_name):
    if profile_name == "rookie":
        return 0.0
    turns = remaining_turns(state, configuration)
    click_levels, producer_levels = projected_levels(state, action, quantity)
    before_click = state["zones"].get(action["zone"], {}).get("purchased_click", 0)
    before_producer = state["zones"].get(action["zone"], {}).get("purchased_producer", 0)
    bonus = 0.0

    if (
        action["name"] == "CLICK_UPGRADE"
        and action["zone"] == "ARCADE"
        and before_click < 10 <= click_levels.get("ARCADE", 0)
        and "ARCADE_ON_FIRE" not in memory["unlocked"]
    ):
        expected_clicks = turns * PROFILE_SETTINGS[profile_name]["collect_rate"]
        bonus += state["zones"]["ARCADE"]["click"] * 0.5 * expected_clicks

    active = active_zones(state)
    before_all_ten = all(state["zones"][name]["purchased_producer"] >= 10 for name in active)
    after_all_ten = all(producer_levels.get(name, 0) >= 10 for name in active)
    if (
        action["name"] == "PRODUCER"
        and not before_all_ten
        and after_all_ten
        and len(active) == 3
        and "AUTOMATED_EMPIRE" not in memory["unlocked"]
    ):
        bonus += sum(state["zones"][name]["income"] for name in active) * 0.5 * turns

    before_diversified = len(active) == 3 and all(
        state["zones"][name]["purchased_click"] >= 5
        and state["zones"][name]["purchased_producer"] >= 5
        for name in active
    )
    after_diversified = len(active) == 3 and all(
        click_levels.get(name, 0) >= 5 and producer_levels.get(name, 0) >= 5
        for name in active
    )
    if (
        not before_diversified
        and after_diversified
        and "DIVERSIFIED_TYCOON" not in memory["unlocked"]
    ):
        bonus += turns * (3 * PROFILE_SETTINGS[profile_name]["collect_rate"] + 6)

    if (
        quantity == 10
        and not memory["successful_batch_ten"]
        and action["name"] in ("PRODUCER", "CLICK_UPGRADE")
    ):
        bonus += action["cost10"] * 0.12

    # Reward a threshold crossing, not every level above the threshold.
    if action["name"] == "PRODUCER" and before_producer < 10 <= producer_levels.get(action["zone"], 0):
        bonus += configuration["producer_gain"] * turns * 0.25
    return bonus


def purchase_candidate(
    state,
    configuration,
    memory,
    action,
    quantity,
    cost,
    quantity_token,
    profile_name,
    collect_value,
):
    if action["name"] == "PRODUCER":
        gain = producer_future_gain(state, configuration, action["zone"], quantity)
    else:
        gain = click_future_gain(
            state,
            configuration,
            action["zone"],
            quantity,
            profile_name,
        )
    trophy = visible_trophy_bonus(
        state,
        configuration,
        memory,
        action,
        quantity,
        profile_name,
    )
    settings = PROFILE_SETTINGS[profile_name]
    capital_weight = settings["capital_weight"]
    turns = remaining_turns(state, configuration)
    if profile_name == "magnate" and turns <= max(8, configuration["max_turns"] // 8):
        # Cash is not the winning score. Near the end, MIDAS spends it aggressively
        # when the projected score gain beats the collect action it gives up.
        capital_weight = 0.05 if state["total_earned"] < state["opponent_total"] else 0.12
    utility = gain + trophy - cost * capital_weight - collect_value
    return {
        "command": "CLICK {} {} {}".format(action["zone"], action["name"], quantity_token),
        "utility": utility,
        "gain": gain + trophy,
        "cost": cost,
        "efficiency": (gain + trophy) / max(1.0, cost),
        "action_order": action_order(action),
        "zone_order": zone_order(action["zone"]),
        "quantity": quantity,
    }


def duration_after_purchase(current, units, configuration):
    added = units * configuration["boost_gain"]
    duration = min(configuration["max_boost"], current + added)
    if current > 0:
        duration -= 1
    return max(0, duration)


def old_duration_next_turn(current):
    return max(0, current - 1)


def unboosted_income(state, zone_name):
    return state["zones"][zone_name]["income"] / float(current_market_factor(state, zone_name))


def unboosted_click(state, zone_name):
    return state["zones"][zone_name]["click"] / float(
        current_market_factor(state, zone_name)
    )


def boost_future_gain(state, configuration, action, units, profile_name):
    turns = remaining_turns(state, configuration)
    if turns == 0:
        return 0.0
    target_global = action["zone"] == "GLOBAL"
    old_global = old_duration_next_turn(state["global_boost"])
    new_global = duration_after_purchase(state["global_boost"], units, configuration) if target_global else old_global
    old_locals = {
        name: old_duration_next_turn(state["zones"][name]["boost"])
        for name in active_zones(state)
    }
    new_locals = dict(old_locals)
    if not target_global:
        new_locals[action["zone"]] = duration_after_purchase(
            state["zones"][action["zone"]]["boost"],
            units,
            configuration,
        )

    collect_rate = PROFILE_SETTINGS[profile_name]["collect_rate"]
    gain = 0.0
    for offset in range(1, turns + 1):
        old_auto = 0.0
        new_auto = 0.0
        old_best_click = 0.0
        new_best_click = 0.0
        for name in active_zones(state):
            base_income = unboosted_income(state, name)
            base_click = unboosted_click(state, name)
            old_factor = (2 if old_locals[name] >= offset else 1) * (
                2 if old_global >= offset else 1
            )
            new_factor = (2 if new_locals[name] >= offset else 1) * (
                2 if new_global >= offset else 1
            )
            old_auto += base_income * old_factor
            new_auto += base_income * new_factor
            old_best_click = max(old_best_click, base_click * old_factor)
            new_best_click = max(new_best_click, base_click * new_factor)
        gain += new_auto - old_auto
        gain += collect_rate * (new_best_click - old_best_click)
    return gain


def boost_candidate(
    state,
    configuration,
    action,
    units,
    cost,
    quantity_token,
    collect_value,
):
    gain = boost_future_gain(state, configuration, action, units, "magnate")
    creates_double_energy = False
    if action["zone"] == "GLOBAL":
        creates_double_energy = any(
            state["zones"][name]["boost"] > 0 for name in active_zones(state)
        ) and state["global_boost"] == 0
    else:
        creates_double_energy = state["global_boost"] > 0 and state["zones"][action["zone"]]["boost"] == 0
    if creates_double_energy:
        gain += 5 * sum(unboosted_income(state, name) for name in active_zones(state))
    utility = gain - cost * 0.32 - collect_value
    command = (
        "CLICK {} BOOST MAX".format(action["zone"])
        if quantity_token == "MAX"
        else "CLICK {} BOOST 1".format(action["zone"])
    )
    return {
        "command": command,
        "utility": utility,
        "gain": gain,
        "cost": cost,
        "efficiency": gain / max(1.0, cost),
        "action_order": action_order(action),
        "zone_order": zone_order(action["zone"]),
        "quantity": units,
    }


def candidate_rank(candidate):
    return (
        round(candidate["utility"], 6),
        round(candidate["gain"], 6),
        round(candidate["efficiency"], 9),
        candidate["action_order"],
        candidate["zone_order"],
        candidate["quantity"],
        -candidate["cost"],
        candidate["command"],
    )


def choose_rookie(state, configuration):
    collect_command, collect_value = best_collect(state)
    turns = remaining_turns(state, configuration)
    best = None
    for action in state["actions"]:
        if action["name"] != "PRODUCER" or action["cost1"] > state["cash"]:
            continue
        future_gain = configuration["producer_gain"] * turns
        if future_gain < action["cost1"] + collect_value:
            continue
        candidate = (
            future_gain - action["cost1"] - collect_value,
            -action["cost1"],
            zone_order(action["zone"]),
            action["zone"],
        )
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return collect_command
    return "CLICK {} PRODUCER 1".format(best[3])


def strategic_candidates(state, configuration, memory, profile_name):
    _, collect_value = best_collect(state)
    candidates = []
    for action in state["actions"]:
        if action["name"] in ("PRODUCER", "CLICK_UPGRADE"):
            for quantity, cost, token in quantity_costs(
                action,
                profile_name,
                True,
                state["cash"],
            ):
                candidates.append(
                    purchase_candidate(
                        state,
                        configuration,
                        memory,
                        action,
                        quantity,
                        cost,
                        token,
                        profile_name,
                        collect_value,
                    )
                )
        elif profile_name == "magnate" and action["name"] == "BOOST":
            if action["cost1"] <= state["cash"] and action["max_buyable"] > 0:
                candidates.append(
                    boost_candidate(
                        state,
                        configuration,
                        action,
                        1,
                        action["cost1"],
                        "1",
                        collect_value,
                    )
                )
            if (
                action["max_buyable"] > 1
                and action["cost_max"] > 0
                and action["cost_max"] <= state["cash"]
            ):
                candidates.append(
                    boost_candidate(
                        state,
                        configuration,
                        action,
                        action["max_buyable"],
                        action["cost_max"],
                        "MAX",
                        collect_value,
                    )
                )
    return candidates


def should_save_for_batch(state, configuration, memory, best, collect_value):
    turns = remaining_turns(state, configuration)
    if turns < 8:
        return False
    if (
        state["total_earned"] < state["opponent_total"]
        and turns <= configuration["max_turns"] // 5
    ):
        return False
    near_future_cash = state["cash"] + collect_value * 2 + sum(
        state["zones"][name]["income"] for name in active_zones(state)
    ) * 2
    unaffordable = []
    for action in state["actions"]:
        if action["name"] not in ("PRODUCER", "CLICK_UPGRADE"):
            continue
        for quantity, cost, token in quantity_costs(
            action,
            "magnate",
            False,
            state["cash"],
        ):
            if cost <= state["cash"] or cost > near_future_cash:
                continue
            candidate = purchase_candidate(
                state,
                configuration,
                memory,
                action,
                quantity,
                cost,
                token,
                "magnate",
                collect_value,
            )
            if candidate["utility"] > 0:
                unaffordable.append(candidate)
    if not unaffordable:
        return False
    future = max(unaffordable, key=candidate_rank)
    return future["efficiency"] > best["efficiency"] * 1.35


def choose_strategic(state, configuration, memory, profile_name):
    collect_command, collect_value = best_collect(state)
    candidates = strategic_candidates(state, configuration, memory, profile_name)
    viable = [candidate for candidate in candidates if candidate["utility"] > 0]
    if not viable:
        return collect_command
    best = max(viable, key=candidate_rank)
    if (
        profile_name == "magnate"
        and should_save_for_batch(state, configuration, memory, best, collect_value)
    ):
        return collect_command
    return best["command"]


def choose_command(state, configuration, memory, profile_name):
    if profile_name == "rookie":
        return choose_rookie(state, configuration)
    return choose_strategic(state, configuration, memory, profile_name)


state = read_turn()
if state is not None:
    configuration = configuration_for(state)
    profile_name = resolve_profile(configuration)
    memory = new_memory()
    while True:
        update_memory(memory, state)
        print(choose_command(state, configuration, memory, profile_name), flush=True)
        state = read_turn()
        if state is None:
            break

